import { readFileSync } from 'node:fs'

const env = Object.fromEntries(
  readFileSync('/home/electronica-care/ezy-prep/exam/app/.env.local', 'utf8')
    .split('\n')
    .filter((l) => /^[A-Z_]+=/.test(l))
    .map((l) => {
      const i = l.indexOf('=')
      return [l.slice(0, i), l.slice(i + 1).replace(/^"|"$/g, '')]
    }),
)
const SUPA = 'http://127.0.0.1:54321'
const APP = 'http://127.0.0.1:3000'
const PW = env.SEED_PASSWORD || 'RentDemo#2026'
const [aisyahLease, benLease] = process.argv.slice(2)

async function token(email) {
  const r = await fetch(`${SUPA}/auth/v1/token?grant_type=password`, {
    method: 'POST',
    headers: { apikey: env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY, 'content-type': 'application/json' },
    body: JSON.stringify({ email, password: PW }),
  })
  const j = await r.json()
  if (!j.access_token) throw new Error(`login failed for ${email}: ${r.status}`)
  return j.access_token
}

async function call(label, tok, method, path, body) {
  const r = await fetch(`${APP}${path}`, {
    method,
    headers: { authorization: `Bearer ${tok}`, ...(body ? { 'content-type': 'application/json' } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  })
  const text = await r.text()
  console.log(`${label}: ${method} ${path} -> ${r.status} ${text.length > 400 ? text.slice(0, 400) + '...' : text}`)
  return { status: r.status, json: text ? JSON.parse(text) : null }
}

const manager = await token('manager@northwind.test')
const staff = await token('staff@northwind.test')
const aisyah = await token('aisyah@northwind.test')
const beta = await token('manager@beta.test')

const lease = await call('manager', manager, 'GET', `/api/leases/${aisyahLease}`)
console.log('lease:', JSON.stringify(lease.json.lease))
for (const inv of lease.json.invoices) {
  console.log(`  invoice ${inv.kind} p=${inv.periodIndex} ${inv.periodStart}..${inv.periodEnd} due ${inv.dueDate} amount ${inv.amountSen} paid ${inv.paidSen} ${inv.status}`)
}
for (const p of lease.json.payments) console.log(`  payment ${p.method} ${p.amountSen} unapplied ${p.unappliedSen} ${p.status} ${p.receivedAt}`)

await call('manager', manager, 'GET', '/api/reports/collections?from=2026-01&to=2026-03')
await call('aisyah own lease', aisyah, 'GET', `/api/leases/${aisyahLease}`).then((r) => r.status)
await call('aisyah Ben lease', aisyah, 'GET', `/api/leases/${benLease}`)
await call('aisyah POST payment', aisyah, 'POST', `/api/leases/${aisyahLease}/payments`, { amountSen: 100, method: 'cash', receivedAt: '2026-03-02T10:00:00+08:00' })
const approvedId = lease.json.payments.find((p) => p.method === 'bank_transfer').id
await call('staff approve', staff, 'POST', `/api/payments/${approvedId}/approve`)
await call('beta manager Aisyah lease', beta, 'GET', `/api/leases/${aisyahLease}`)
await call('manager approve approved', manager, 'POST', `/api/payments/${approvedId}/approve`)

